// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import {
  mergeStatementLinks,
  statementConnector,
  statementLinksOf,
} from "../../../main/frontend/graph-explorer/statement-links.ts";
import { mergeTriples, removeGraphNodes, cloneGraph } from "../../../main/frontend/graph-explorer/graph-operations.ts";
import { bindingsToTriples, tripleEdgeId } from "../../../main/frontend/graph-explorer/graph-terms.ts";
import { canvasGraph } from "../../../main/frontend/graph-explorer/graph-canvas-scope.ts";

const RDF_REIFIES = "http://www.w3.org/1999/02/22-rdf-syntax-ns#reifies";
const uri = (value) => ({ type: "uri", value });
const triple = (subject, predicate, object) => ({ type: "triple", value: { subject, predicate, object } });
const rows = [
  { source: uri("urn:alice"), predicate: uri("urn:knows"), target: uri("urn:bob") },
  { source: uri("urn:claim"), predicate: uri(RDF_REIFIES), target: triple(uri("urn:alice"), uri("urn:knows"), uri("urn:bob")) },
  { source: { type: "bnode", value: "r1" }, predicate: uri(RDF_REIFIES), target: triple(uri("urn:alice"), uri("urn:age"), { type: "literal", value: "39" }) },
  { source: uri("urn:dave"), predicate: uri("urn:doubts"), target: triple(uri("urn:x"), uri("urn:p"), triple(uri("urn:a"), uri("urn:b"), uri("urn:c"))) },
];

test("rows whose object is a triple term become statement links; nested triple terms are left out", () => {
  const found = statementLinksOf(rows);
  assert.deepEqual(
    found.map(({ link }) => [link.source, link.predicate, link.subject, link.statementPredicate]),
    [
      ["urn:claim", RDF_REIFIES, "urn:alice", "urn:knows"],
      [found[1].link.source, RDF_REIFIES, "urn:alice", "urn:age"],
    ],
  );
  assert.equal(found[0].link.statementEdgeId, tripleEdgeId("urn:alice", "urn:knows", "urn:bob"));
  assert.match(found[1].link.source, /r1/);
});

test("merged links bring their source node, are kept once, and go when their source is hidden", () => {
  let graph = mergeTriples({ nodes: [], edges: [], revision: 0 }, bindingsToTriples(rows));
  graph = mergeStatementLinks(graph, statementLinksOf(rows), "batch-1");
  graph = mergeStatementLinks(graph, statementLinksOf(rows), "batch-2");
  assert.equal(graph.statementLinks.length, 2);
  assert.ok(graph.nodes.some((node) => node.id === "urn:claim" && node.kind === "iri"));
  assert.ok(graph.nodes.some((node) => node.kind === "blank"));
  assert.equal(graph.statementLinks[0].batchId, "batch-1");

  assert.equal(canvasGraph(graph, false).statementLinks.length, 2, "the canvas draws them");
  assert.equal(cloneGraph(graph).statementLinks.length, 2, "history keeps them");
  assert.equal(mergeTriples(graph, [], false).statementLinks.length, 2, "adding results keeps them");
  assert.equal(mergeTriples(graph, [], true).statementLinks, undefined, "replacing drops them");
  assert.equal(removeGraphNodes(graph, new Set(["urn:claim"])).statementLinks.length, 1);
});

test("a connector runs from the node to the middle of the statement's edge", () => {
  const link = statementLinksOf(rows)[0].link;
  const nodes = new Map([["urn:claim", { id: "urn:claim", label: "Claim", kind: "iri", x: 0, y: 0 }]]);
  const curve = { path: "", start: { x: 100, y: 100 }, control: { x: 150, y: 50 }, end: { x: 200, y: 100 } };
  const connector = statementConnector(link, nodes, new Map([[link.statementEdgeId, curve]]));
  assert.deepEqual(connector.end, { x: 150, y: 75 });
  assert.match(connector.path, /^M0,0 L150,75$/);
  assert.equal(statementConnector(link, nodes, new Map()), null, "no connector while the statement is not drawn");
});
